package httpserver
import("net/http";"net/http/httptest";"testing")
func TestRouting(t *testing.T){h:=New("https://panel.example.test","https://mcp.example.test","https://upload.example.test","sites.example.test",http.HandlerFunc(func(w http.ResponseWriter,r *http.Request){w.WriteHeader(201)}),http.HandlerFunc(func(w http.ResponseWriter,r *http.Request){w.WriteHeader(202)}),http.HandlerFunc(func(w http.ResponseWriter,r *http.Request){w.WriteHeader(203)}),http.HandlerFunc(func(w http.ResponseWriter,r *http.Request){w.WriteHeader(204)})); for _,x:=range []struct{host,path,method string; want int}{{"PANEL.EXAMPLE.TEST:443","/","GET",201},{"mcp.example.test","/mcp","POST",202},{"panel.example.test","/mcp","POST",404},{"mcp.example.test","/","GET",404},{"upload.example.test","/uploads/a","PUT",203},{"upload.example.test","/api/session","GET",404},{"s-0123456789abcdef0123456789abcdef.sites.example.test","/healthz","GET",204},{"s-0123456789abcdef0123456789abcdef.sites.example.test:8443","/","GET",403},{"evil.test","/","GET",403},{"evil.test","/healthz","HEAD",200},{"evil.test","/healthz","POST",405},{"mcp.example.test","/mcp/","GET",404}} {r:=httptest.NewRequest(x.method,"http://test"+x.path,nil);r.Host=x.host;r.Header.Set("X-Forwarded-Host","panel.example.test");w:=httptest.NewRecorder();h.ServeHTTP(w,r);if w.Code!=x.want {t.Errorf("%+v got %d",x,w.Code)}}}
